import React, { useCallback, useEffect, useState } from 'react';
import {
  Bar,
  BarChart,
  CartesianGrid,
  Legend,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import {
  Button,
  FormActions,
  Input,
  dispatchAppToast,
} from '@linm-soft-org/linm-web-common-components';
import { Spin, Text, Title } from '@/components/common';
import { useAppDispatch } from '../../../store/hooks';
import { fpcService } from '../../../services/fpc/service';
import type { PlanVsActualDto, PlanVsActualLineDto } from '../../../services/fpc/types';
import { useFpcPermissions } from '../../../utils/fpcPermissionCode';
import styles from './PlanVsActualPage.module.css';

const TEST_ID = 'plan-vs-actual';

const fVnd = (v: number): string =>
  new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }).format(v);

const fCompact = (v: number): string => {
  const abs = Math.abs(v);
  const sign = v < 0 ? '-' : '';
  if (abs >= 1_000_000_000) return `${sign}${(abs / 1_000_000_000).toFixed(1)} tỷ`;
  if (abs >= 1_000_000) return `${sign}${(abs / 1_000_000).toFixed(0)} tr`;
  if (abs >= 1_000) return `${sign}${(abs / 1_000).toFixed(0)} ng`;
  return `${v.toLocaleString('vi-VN')}`;
};

const chartCurrency = (v: number): string => `${(v / 1_000_000).toFixed(0)}tr`;

const pct = (v: number): string => `${v >= 0 ? '+' : ''}${v.toFixed(1)}%`;

function todayLocalYmd(): string {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

function monthStartYmd(): string {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-01`;
}

function formatDisplayDate(isoOrYmd?: string | null): string {
  if (!isoOrYmd) return '—';
  const raw = isoOrYmd.slice(0, 10);
  const [y, m, d] = raw.split('-');
  if (!y || !m || !d) return isoOrYmd;
  return `${d}/${m}/${y}`;
}

function isInflow(direction: string): boolean {
  const d = (direction || '').toLowerCase();
  return d === 'inflow' || d === 'thu' || d === 'i';
}

/** Tỷ lệ = (thực tế − KH) / KH; KH = 0 và có thực tế → ±100% theo dấu chênh lệch. */
function lineVariancePercent(line: PlanVsActualLineDto): number {
  const plan = Math.abs(line.planAmount ?? 0);
  const actual = Math.abs(line.actualAmount ?? 0);
  const variance = line.variance ?? actual - plan;
  if (plan !== 0) return (variance / plan) * 100;
  if (actual !== 0) return variance >= 0 ? 100 : -100;
  return 0;
}

function statusBadge(percent: number): { label: string; className: string } {
  const abs = Math.abs(percent);
  if (abs > 10) return { label: 'Lệch', className: styles.statusRed };
  if (abs > 5) return { label: 'Theo dõi', className: styles.statusYellow };
  return { label: 'OK', className: styles.statusGreen };
}

const PlanVsActualPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const { canViewPlanVsActual, canExportReports } = useFpcPermissions();

  const defaultStart = monthStartYmd();
  const defaultEnd = todayLocalYmd();
  const [periodStart, setPeriodStart] = useState(defaultStart);
  const [periodEnd, setPeriodEnd] = useState(defaultEnd);
  const [appliedStart, setAppliedStart] = useState(defaultStart);
  const [appliedEnd, setAppliedEnd] = useState(defaultEnd);
  const [data, setData] = useState<PlanVsActualDto | null>(null);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState(false);

  const loadReport = useCallback(async (start: string, end: string) => {
    setLoading(true);
    setLoadError(false);
    try {
      const result = await fpcService.getPlanVsActual({ periodStart: start, periodEnd: end });
      setData(result);
      setAppliedStart(start);
      setAppliedEnd(end);
    } catch {
      setData(null);
      setLoadError(true);
      dispatchAppToast(dispatch, {
        message: 'Không thể tải báo cáo kế hoạch vs thực tế',
        type: 'error',
      });
    } finally {
      setLoading(false);
    }
  }, [dispatch]);

  useEffect(() => {
    const t = window.setTimeout(() => {
      void loadReport(appliedStart, appliedEnd);
    }, 0);
    return () => window.clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- initial load; Xem/Làm mới gọi loadReport
  }, []);

  const handleView = () => {
    if (!periodStart || !periodEnd) {
      dispatchAppToast(dispatch, { message: 'Vui lòng chọn kỳ xem', type: 'error' });
      return;
    }
    if (periodStart > periodEnd) {
      dispatchAppToast(dispatch, { message: 'Từ ngày phải ≤ Đến ngày', type: 'error' });
      return;
    }
    void loadReport(periodStart, periodEnd);
  };

  const handleRefresh = () => {
    void loadReport(appliedStart, appliedEnd);
  };

  if (!canViewPlanVsActual) {
    return (
      <div className={styles.page} data-testid={`${TEST_ID}-page`}>
        <div className={styles.empty}>
          <Text type="secondary">Bạn không có quyền xem kế hoạch vs thực tế.</Text>
        </div>
      </div>
    );
  }

  const lines = data?.lines ?? [];
  const inflowLines = lines.filter(l => isInflow(l.direction));
  const netDelta = data
    ? (data.netPlanCashflow ?? 0) - (data.netActualCashflow ?? 0)
    : 0;

  return (
    <div className={styles.page} data-testid={`${TEST_ID}-page`}>
      <div className={styles.headerCard}>
        <div className={styles.headerTop}>
          <div>
            <Title level={4}>
              <i className="fas fa-balance-scale" style={{ marginRight: 8, color: '#2563eb' }} />
              Kế hoạch so với thực tế
            </Title>
            <Text type="secondary">
              So sánh plan / actual theo khoản mục
              {` · ${formatDisplayDate(appliedStart)} – ${formatDisplayDate(appliedEnd)}`}
            </Text>
          </div>
          <FormActions align="end">
            <Button onClick={handleRefresh} data-testid={`${TEST_ID}-refresh-btn`}>
              <i className="fas fa-redo" /> Làm mới
            </Button>
            {canExportReports && (
              <Button
                variant="secondary"
                disabled={!data}
                onClick={() => window.print()}
                data-testid={`${TEST_ID}-export-btn`}
              >
                <i className="fas fa-print" /> In
              </Button>
            )}
          </FormActions>
        </div>

        <div className={styles.filterRowPeriod}>
          <div className={styles.filterField}>
            <label className={styles.filterLabel} htmlFor={`${TEST_ID}-from`}>Từ ngày</label>
            <Input
              id={`${TEST_ID}-from`}
              type="date"
              value={periodStart}
              onChange={e => setPeriodStart(e.target.value)}
              data-testid={`${TEST_ID}-from`}
            />
          </div>
          <div className={styles.filterField}>
            <label className={styles.filterLabel} htmlFor={`${TEST_ID}-to`}>Đến ngày</label>
            <Input
              id={`${TEST_ID}-to`}
              type="date"
              value={periodEnd}
              onChange={e => setPeriodEnd(e.target.value)}
              data-testid={`${TEST_ID}-to`}
            />
          </div>
          <FormActions align="end">
            <Button variant="primary" onClick={handleView} data-testid={`${TEST_ID}-view-btn`}>
              <i className="fas fa-search" /> Xem
            </Button>
          </FormActions>
        </div>
      </div>

      {loading && (
        <div className={styles.loading} data-testid={`${TEST_ID}-loading`}>
          <Spin />
          <Text type="secondary">Đang tải kế hoạch vs thực tế…</Text>
        </div>
      )}

      {!loading && loadError && (
        <div className={styles.empty} data-testid={`${TEST_ID}-error`}>
          <Text type="secondary">Không tải được dữ liệu. Thử Làm mới hoặc đổi kỳ.</Text>
          <Button variant="primary" onClick={handleRefresh}>Thử lại</Button>
        </div>
      )}

      {!loading && !loadError && data && (
        <div className={styles.contentPanel} data-testid={`${TEST_ID}-content`}>
          <div className={styles.statsRow}>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Kế hoạch thu</span>
              <span className={styles.statValue}>{fCompact(Math.abs(data.totalPlanInflow ?? 0))}</span>
              <span className={styles.statTrend}>Thực tế: {fCompact(Math.abs(data.totalActualInflow ?? 0))}</span>
            </div>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Kế hoạch chi</span>
              <span className={styles.statValue}>{fCompact(Math.abs(data.totalPlanOutflow ?? 0))}</span>
              <span className={styles.statTrend}>Thực tế: {fCompact(Math.abs(data.totalActualOutflow ?? 0))}</span>
            </div>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Kế hoạch dòng tiền thuần</span>
              <span className={(data.netPlanCashflow ?? 0) >= 0 ? `${styles.statValue} ${styles.positive}` : `${styles.statValue} ${styles.negative}`}>
                {fCompact(data.netPlanCashflow)}
              </span>
              <span className={styles.statTrend}>Thực tế: {fCompact(data.netActualCashflow)}</span>
            </div>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Chênh lệch</span>
              <span className={`${styles.statValue} ${netDelta >= 0 ? styles.negative : styles.positive}`}>
                {fCompact(netDelta)}
              </span>
            </div>
          </div>

          <div className={styles.chartCardFull} data-testid={`${TEST_ID}-chart`}>
            <div className={styles.chartCardHeader}>
              <h3 className={styles.chartTitle}>Kế hoạch so với thực tế theo khoản mục (Thu)</h3>
              <span className={styles.sectionBadge}>Biểu đồ cột nhóm</span>
            </div>
            {inflowLines.length === 0 ? (
              <Text type="secondary">Chưa có khoản mục thu trong kỳ.</Text>
            ) : (
              <ResponsiveContainer width="100%" height={320}>
                <BarChart data={inflowLines}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
                  <XAxis dataKey="categoryName" tick={{ fontSize: 10 }} angle={-15} textAnchor="end" height={50} />
                  <YAxis tickFormatter={chartCurrency} tick={{ fontSize: 11 }} />
                  <Tooltip formatter={(v: number) => fVnd(v)} />
                  <Legend />
                  <Bar dataKey="planAmount" name="Kế hoạch" fill="#3b82f6" radius={[4, 4, 0, 0]} />
                  <Bar dataKey="actualAmount" name="Thực tế" fill="#10b981" radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            )}
          </div>

          <div className={styles.tableWrapper}>
            <table className={styles.table} data-testid={`${TEST_ID}-table`}>
              <thead>
                <tr>
                  <th>Khoản mục</th>
                  <th>Hướng</th>
                  <th>Kế hoạch</th>
                  <th>Thực tế</th>
                  <th>Chênh lệch</th>
                  <th>Tỷ lệ</th>
                  <th>Trạng thái</th>
                </tr>
              </thead>
              <tbody>
                {lines.length === 0 ? (
                  <tr>
                    <td colSpan={7}><Text type="secondary">Không có dòng khoản mục.</Text></td>
                  </tr>
                ) : (
                  lines.map((line, i) => {
                    const ratio = lineVariancePercent(line);
                    const badge = statusBadge(ratio);
                    return (
                      <tr key={`${line.categoryCode}-${i}`}>
                        <td style={{ fontWeight: 500 }}>{line.categoryName || line.categoryCode}</td>
                        <td className={styles.colCenter}>
                          <span className={`${styles.phaseTag} ${isInflow(line.direction) ? styles.phaseP0 : styles.phaseP1}`}>
                            {isInflow(line.direction) ? 'Thu' : 'Chi'}
                          </span>
                        </td>
                        <td className={styles.colAmount}>{fVnd(Math.abs(line.planAmount ?? 0))}</td>
                        <td className={styles.colAmount}>{fVnd(Math.abs(line.actualAmount ?? 0))}</td>
                        <td className={styles.colAmount}>
                          <span style={{ color: (line.variance ?? 0) >= 0 ? '#059669' : '#ef4444', fontWeight: 600 }}>
                            {(line.variance ?? 0) >= 0 ? '+' : ''}{fVnd(line.variance ?? 0)}
                          </span>
                        </td>
                        <td className={styles.colCenter}>
                          <span style={{ color: ratio >= 0 ? '#059669' : '#ef4444', fontWeight: 600 }}>
                            {pct(ratio)}
                          </span>
                        </td>
                        <td className={styles.colCenter}>
                          <span className={`${styles.statusBadge} ${badge.className}`}>
                            {badge.label}
                          </span>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

export default PlanVsActualPage;
